INSERT INTO `customer` VALUES (94, NULL, '国家虚拟现实创新中心（青岛）', '刘剑', '18663950082', 12, '山东省,青岛市', '青岛市崂山区株洲路170号', NULL, NULL, NULL, 33, NULL, NULL, NULL, NULL, '聚焦制约我国虚拟现实产业发展的关键共性技术难题，建设关键共性技术研发、测试验证、检测、技术服务、人才培养和国际合作等平台，构建覆盖虚拟现实全产业链的产业创新生态，推动虚拟现实产业高质量发展。', NULL, 11460, '2024-10-30 11:24:11', NULL, '2024-10-30 11:24:11', 0, 1, NULL, NULL, NULL, 11430);
