INSERT INTO `customer` VALUES (112, NULL, '峰岹科技（青岛）有限公司', '王云', '18380448749', 10, '山东省,青岛市', '山东省青岛市崂山区科苑纬一路1号青岛国际创新园二期D2楼2301室', NULL, NULL, NULL, 33, NULL, NULL, NULL, NULL, '峰岹科技成立于2010年，是一家专业的电机驱动芯片半导体公司，致力为各种电机系统提供高质量的驱动和控制芯片，及电机技术的咨询服务。我们提供的芯片应用领域涵盖工业设备、运动控制、电动工具、消费电子、智能机器人、IT及通信等驱动控制领域。', NULL, 11460, '2024-10-31 16:22:16', NULL, '2024-10-31 16:22:16', 0, 1, NULL, NULL, NULL, NULL);
