INSERT INTO `customer` VALUES (157, NULL, '中国科学院上海微系统与信息技术研究所', '汪明亮', '13301699082', 12, '上海市,长宁区', '上海市长宁区长宁路865号', NULL, NULL, NULL, 27, NULL, NULL, NULL, NULL, '中国科学院上海微系统与信息技术研究所原名中国科学院上海冶金研究所，前身是成立于1928年的国立中央研究院工程研究所，是中国最早的工学研究机构之一。新中国成立后隶属中国科学院，曾命名中国科学院工学实验馆、中国科学院冶金陶瓷研究所。2001年8月，根据科研领域和科技发展目标的调整，更名为中国科学院上海微系统与信息技术研究所（简称上海微系统所）', NULL, 11439, '2024-11-01 14:25:54', 11439, '2025-07-08 10:06:58', 0, 2, NULL, NULL, NULL, NULL);
