INSERT INTO `customer` VALUES (269, NULL, '鹏城国家实验室', '无联系人', '12345678910', 12, '广东省,深圳市', '深圳市南山区西丽街道留仙洞万科云城一期8栋', NULL, NULL, NULL, 27, NULL, NULL, NULL, NULL, '鹏城实验室（Peng Cheng Laboratory），是中央批准成立的网络通信领域新型科研机构 ，始建于2018年3月，从事该领域战略性、前瞻性、基础性重大科学问题和关键核心技术研究，是国家战略科技力量的重要组成部分。实验室总部位于广东省深圳市。研究方向是网络通信、网络空间和网络智能。使命任务是聚焦服务国家宽带通信和新型网络战略，服务国家粤港澳大湾区和深圳中国特色社会主义先行示范区建设', NULL, 11439, '2024-11-04 10:36:15', 11439, '2025-07-08 10:05:36', 0, 2, NULL, NULL, NULL, NULL);
