INSERT INTO `customer` VALUES (322, NULL, '南京ICC', '孙飞', 'June-to-Fly', 9, '江苏省,南京市', '浦口区华富智溪谷4号楼路1号', NULL, NULL, NULL, 28, NULL, NULL, NULL, NULL, '南京芯火平台是国家组织，有一定的实验能力，平台资源比较丰富。目前更多的是在自己的平台上做一些流片的服务，测试之类的。', NULL, 11451, '2024-11-26 22:14:34', NULL, '2024-11-26 22:14:34', 0, 1, NULL, NULL, NULL, NULL);
INSERT INTO `customer` VALUES (323, NULL, '融创微电子', '张细', '18975133067', 10, '湖南省,长沙市', '岳麓区尖山路18号中电软件园二期第A5栋', NULL, NULL, NULL, 28, NULL, NULL, NULL, NULL, '融创微电子主要有高可靠存储产品线、SOC 产品线、高可靠设计与IP 平台三大核心业务。高可靠存储线产品全面覆盖SRAM、EEPROM、FLASH 等存储系列，已广泛应用于客户产品；SOC 产品线包括MCU 产品与专用SOC 产品，产品应用覆盖从消费类电子到工控领域。', NULL, 11451, '2024-11-26 22:17:51', NULL, '2024-11-26 22:17:51', 0, 1, NULL, NULL, NULL, NULL);
INSERT INTO `customer` VALUES (324, NULL, '湖南大学', '陈卓俊', 'zhuojunchen', 13, '湖南省,长沙市', '岳麓区中建智慧谷E13-1号', NULL, NULL, NULL, 28, NULL, NULL, NULL, NULL, '陈老师主要就职于湖南大学集成电路学院，受聘于长沙半导体技术与应用创新研究院，目前有一个设备的项目在走流程。\n\n其他联系人：\n赵卓影是湖南大学机电系在读博士，目前在做的还是自己的科研项目，该芯片有流片的可能，后期有跟进必要', NULL, 11451, '2024-11-26 22:20:28', NULL, '2024-11-26 22:20:28', 0, 1, NULL, NULL, NULL, NULL);
INSERT INTO `customer` VALUES (325, NULL, '湖南大学1', '赵卓影', 'DZWXBDWM907859339', 13, '湖南省,长沙市', '湖南大学机电系', NULL, NULL, NULL, 28, NULL, NULL, NULL, NULL, '赵卓影是湖南大学机电系在读博士，目前在做的还是自己的科研项目，该芯片有流片的可能，后期有跟进必要', NULL, 11451, '2024-11-26 22:25:16', NULL, '2024-12-09 16:38:11', 1, 1, NULL, NULL, NULL, NULL);
INSERT INTO `customer` VALUES (326, NULL, '湖南匠心', '邢海源', 'xhy940412', 10, '湖南省,长沙市', '开福区凯乐楚源B座1306室', NULL, NULL, NULL, 28, NULL, NULL, NULL, NULL, '该公司主要是国防科大的老师与学生做的一个公司，目前做的比较好的是SMIC、UMC28的存储类芯片，后面可能有合作机会。', NULL, 11451, '2024-11-26 22:30:12', NULL, '2024-11-26 22:30:12', 0, 1, NULL, NULL, NULL, NULL);
INSERT INTO `customer` VALUES (327, NULL, '西交空间网络安全研究院', '宫海天', 'ght_vb', 12, '浙江省,绍兴市', '诸暨市浦阳路18号科创园3号', NULL, NULL, NULL, 28, NULL, NULL, NULL, NULL, '研究院面向网络与数据安全领域科技发展前沿，大力开展网络安全自主可控专用芯片、软硬结合内外网安全管控系统以及行业安全管控整体解决方案等网络空间安全关键核心技术研究，建设有安全专用芯片研究中心、安全管控系统研究中心、行业解决方案研究中心等三个研究中心，打造集科学研究、成果转化、人才引育、产业孵化于一体的新型研发机构。', NULL, 11451, '2024-11-26 22:33:35', NULL, '2024-11-26 22:33:35', 0, 1, NULL, NULL, NULL, NULL);
INSERT INTO `customer` VALUES (328, NULL, '成都振芯科技', '李志成', 'a821212308', 9, '四川省,成都市', '高朋大道1号', NULL, NULL, NULL, 28, NULL, NULL, NULL, NULL, '该公司有国资背景，在成都本地属于领头企业之一。主要产品有北斗相关器件、视频信号传输类芯片、MEMS传感类芯片，以及各类工业摄像机成品等。', NULL, 11451, '2024-11-26 22:37:02', NULL, '2024-11-26 22:37:02', 0, 1, NULL, NULL, NULL, NULL);
INSERT INTO `customer` VALUES (329, NULL, '成都奈芯', '聂瑞', 'wxid_qtx7jytbt16321', 10, '四川省,成都市', '高新区天府大道北段1700号1栋1单元10层1012号', NULL, NULL, NULL, 28, NULL, NULL, NULL, NULL, '奈芯主要做芯片逆向，跟该公司合作主要是部分客户有重叠，所以经常会交流一部分客户资源。', NULL, 11451, '2024-11-26 22:42:20', NULL, '2024-11-26 22:42:20', 0, 1, NULL, NULL, NULL, NULL);
