INSERT INTO `customer` VALUES (355, NULL, '许昌电气职业学院', '滕老师', '177 9678 7559', 13, '河南省,许昌市', '河南省许昌市魏文路与永昌大道（北环路）交叉口 ', NULL, NULL, NULL, 28, NULL, NULL, NULL, NULL, '许昌电气职业学院是经教育部备案，2011年河南省人民政府批准，许昌市人民政府主办的一所多学科、全日制公办普通高等职业院校。学院实行多层次办学体制，集高职教育、技工教育、电大开放教育、社会培训四大功能于一体\n许昌电气职业学院现开设电气自动化技术、机电一体化技术、供用电技术、数控技术、计算机应用技术、计算机网络技术、电子商务技术、电力系统继电保护与自动化技术、模具设计与制造、材料成型与控制技术、机电设备维修与管理、汽车检测与维修技术、新能源汽车技术、经济信息管理、工程造价、会计、旅游管理、广告设计与制作、播音与主持、空中乘务等54个专业。学院师资力量雄厚，拥有专职教师和双师教师471人，其中副高级以上职称90人，教授及特聘教授38人，博士硕士共92人。全日制高职在校生、全日制技校生、开放教育注册生18850人。', NULL, 11455, '2025-03-17 15:56:21', NULL, '2025-03-17 15:56:21', 0, 1, NULL, NULL, NULL, NULL);
