INSERT INTO `customer` VALUES (416, NULL, '百度（青岛）智创基地', '赵孟', '18553280257', 10, '山东省,青岛市', '青岛市城阳区火炬路与汇智桥路交叉路口往东南约150米', NULL, NULL, NULL, 33, NULL, NULL, NULL, NULL, '百度（青岛）智创基地众创空间是2020年中华人民共和国科学技术部确定的国家备案众创空间 ，成立于2017年6月，由青岛高新区管委会、北京百度网讯科技有限公司和晶兆信息科技共同打造，重点发展大数据、人工智能、云计算等领域的创新创业项目。截至2020年3月，已有150余家企业入驻，提供一站式资源导入、零租金办公等服务支持', NULL, 11460, '2025-10-17 15:54:04', NULL, '2025-10-17 15:54:04', 0, 1, NULL, NULL, NULL, NULL);
INSERT INTO `customer` VALUES (417, NULL, '青岛高层次人才创业中心', '孙宇', '13070838317', 10, '山东省,青岛市', '山东省青岛市崂山区株洲路153号', NULL, NULL, NULL, 33, NULL, NULL, NULL, NULL, '青岛高层次人才创业中心（简称“高创中心”）成立于2011年9月份，位于青岛市崂山区株洲路153号，建筑面积3万余平方米，由青岛市人力资源和社会保障局主办。园区旨在吸引扶持海内外高层次人才来青创业发展，研发转化具有国际先进水平的科技成果，培育一批战略性新兴企业', NULL, 11460, '2025-10-17 15:54:04', NULL, '2025-10-17 15:54:04', 0, 1, NULL, NULL, NULL, NULL);
INSERT INTO `customer` VALUES (418, NULL, '国家技术转移中心东部中心青岛基地', '牛振涛', '15963000640', 9, '山东省,青岛市', '山东省青岛市城阳区春阳路88号', NULL, NULL, NULL, 33, NULL, NULL, NULL, NULL, '国家技术转移人才培养基地（东部中心）是经科学技术部火炬高技术产业开发中心备案，承担技术转移专业人员能力等级培养任务的实体培训机构，通过在技术成果转移转化的成果端、需求端、政策端、服务端的体系建设，致力于打造适应于中国国情并赋能产业升级的专业化、职业化、国际化的技术转移转化国际人才港。', NULL, 11460, '2025-10-17 15:54:04', NULL, '2025-10-17 15:54:04', 0, 1, NULL, NULL, NULL, NULL);
