INSERT INTO `customer_copy1` VALUES (97, NULL, '青岛展诚科技有限公司', '孙延辉', '19862188336', 10, '山东省,青岛市', '山东省青岛市市南区延安三路109号华通中联创意产业园B2栋3层', NULL, NULL, NULL, 27, NULL, NULL, NULL, NULL, '青岛展诚科技有限公司成立于2002年，是一家专业的集成电路后端设计服务公司，其设计服务团队拥有超过二十年的IC后端设计服务经验，主要服务于台湾积体电路（TSMC）、海思半导体（华为）以及联发科技（MTK）等国际TOP20的集成电路设计及代工企业。公司目前拥有超过100名的集成电路后端设计工程师，先后多次参加国家核高基一号重大专项项目，与30多家Foundry保持着合作关系，为国内外150余家集成电', NULL, 11460, '2024-10-31 16:00:51', NULL, '2024-10-31 16:00:51', 0);
INSERT INTO `customer_copy1` VALUES (99, NULL, '垣矽技术（青岛)有限公司', '杨军', '15650160091', 10, '山东省,青岛市', '山东省青岛市崂山区海尔路180号大荣世纪综合楼（大荣中心）2号楼20层2002室', NULL, NULL, NULL, 33, NULL, NULL, NULL, NULL, '垣矽技术是一家以高性能模拟射频芯片作为主要业务方向的创新型芯片设计公司。www.raysitek.com', NULL, 11460, '2024-10-31 16:22:16', NULL, '2024-10-31 16:22:16', 0);
INSERT INTO `customer_copy1` VALUES (100, NULL, '恩芯半导体（青岛）有限公司', '李良玉', '13553093919', 10, '山东省,青岛市', '山东省青岛市崂山区同安路880号5号楼220室', NULL, NULL, NULL, 33, NULL, NULL, NULL, NULL, '恩芯半导体（青岛）有限公司专注于太赫兹领域的通讯芯片研发和通讯协议的开发设计。', NULL, 11460, '2024-10-31 16:22:16', NULL, '2024-10-31 16:22:16', 0);
INSERT INTO `customer_copy1` VALUES (101, NULL, '仁凰（青岛）集成电路有限公司', '高涛', '15315316576', 10, '山东省,青岛市', '山东省青岛市崂山区科苑纬一路1号创新园二期1号D2座千山大厦2302', NULL, NULL, NULL, 33, NULL, NULL, NULL, NULL, '由中国科学技术团队成立，主要面向大功率射频芯片的研发，目前公司还处于研发阶段，其产品以定制化为主', NULL, 11460, '2024-10-31 16:22:16', NULL, '2024-10-31 16:22:16', 0);
INSERT INTO `customer_copy1` VALUES (102, NULL, '山东炎一智能科技有限公司', '林克坚', '13156215680', 10, '山东省,青岛市', '山东省青岛市崂山区松岭路169号青岛国际创新园D2座904', NULL, NULL, NULL, 33, NULL, NULL, NULL, NULL, '山东炎一智能科技有限公司2017年11月注册成立于崂山，青岛20人左右，是一家集研发、销售、生产（深圳）、采购、技术支持于一体的高技术企业。公司做为业界领先的物联网设备及方案提供商，秉承“大道至简，知行合一”的企业理念，专注于医疗健康领域与先进工业制造领域的无线传感网络设备的研发和制造。\n    目前，公司正致力于物联网-超低功耗射频MCU研发，用于解决行业中依赖进口芯片的现状。Hyper M10P是一款多协议低于 1GHz 和 2.4GHz 无线 MCU，面向无线 M-Bus、IEEE 802.15.4g、支持 IPv6 的智能对象、 低功耗 Bluetooth® 5 的专有系统，是一款高度集成、真正的物联网SoC。', NULL, 11460, '2024-10-31 16:22:16', NULL, '2024-10-31 16:22:16', 0);
INSERT INTO `customer_copy1` VALUES (103, NULL, '青岛云威半导体科技有限公司', '高丽雅', '18678967889', 10, '山东省,青岛市', '山东省青岛市崂山区科苑纬一路1号青岛国际创新园B座402室', NULL, NULL, NULL, 33, NULL, NULL, NULL, NULL, '作为一家新成立的以芯片研发设计为主的科技公司，投资方之一，上海云间半导体科技股份有限公司，核心团队有多年CPU和SOC芯片设计经验，曾经参与设计中国第一款多核、多线程、CPU+DSP异构架构处理器芯片，公司已在规划自主研发一款高性能的32位MCU，应用于智能家居、安防监控、物联网和消费电子等领域。公司要建立完整的体系，包括方案设计、技术支持、市场销售，吸引有经验丰富的工程技术人员与业务服务人员加入。专注为用户提供稳定可靠的集成电路方案设计定制、智能电子产品整体开发设计和技术服务。', NULL, 11460, '2024-10-31 16:22:16', NULL, '2024-10-31 16:22:16', 0);
INSERT INTO `customer_copy1` VALUES (104, NULL, '青岛矽科微电子有限公司', '肖乾', '18954672958', 10, '山东省,青岛市', '山东省青岛市崂山区同安路880号5层G08室', NULL, NULL, NULL, 33, NULL, NULL, NULL, NULL, '青岛矽科微电子有限公司成立于2012年6月12日，坐落于美丽的海滨城市青岛，是一家以中低压沟槽栅 MOSFET、高压平面型MOSFET、快恢复二极管（FRED）、IGBT、碳化硅二极管、电源管理集成电路等国内领先的新型功率半导体芯片和器件，以及相关产品应用电路系统的设计、生产和销售为主营业务的高科技企业。\n   公司产品广泛应用于变频空调、液晶电视、通信电源、计算机电源、太阳能电池、逆变电源、逆变焊机、等离子切割机、电磁加热、变频器、不间断电源、汽车电子、电动车控制器、充电机等领域，具有极其广阔的市场应用前景。', NULL, 11460, '2024-10-31 16:22:16', NULL, '2024-10-31 16:22:16', 0);
